const MESSAGES: Record<Locale, Partial<Record<MessageKey, string>>> = { en, el, it };

export type Translate = (key: MessageKey, vars?: Record<string, string | number>) => string;

/** Missing translations fall back to English; an unknown key comes back as itself. */
export function translator(locale: Locale): Translate {
  return (key, vars) => {
    const template = MESSAGES[locale][key] ?? en[key] ?? key;
    if (!vars) return template;
    return template.replace(/\{(\w+)\}/g, (match, name: string) => String(vars[name] ?? match));
  };
}

export function isLocale(value: unknown): value is Locale {
  return typeof value === "string" && (LOCALES as string[]).includes(value);
}

export function readLocale(): Locale {
  try {
    const stored = localStorage.getItem(LOCALE_STORAGE_KEY);
    if (isLocale(stored)) return stored;
    // First visit: follow the browser, so a Greek phone opens in Greek.
    const preferred = navigator.languages?.map((tag) => tag.split("-")[0]).find(isLocale);
    return preferred ?? "en";
  } catch {
    return "en";
  }
}

export function applyLocale(locale: Locale): void {
  document.documentElement.setAttribute("lang", locale);
}

// Mirrors readLocale/applyLocale, inlined in the document head so <html lang> is right before paint.
export const LOCALE_SCRIPT = `(function(){try{var l=["en","el","it"];var s=localStorage.getItem(${JSON.stringify(LOCALE_STORAGE_KEY)});if(l.indexOf(s)<0){s=(navigator.languages||[navigator.language||"en"]).map(function(t){return String(t).split("-")[0]}).filter(function(t){return l.indexOf(t)>=0})[0]||"en"}document.documentElement.setAttribute("lang",s)}catch(e){}})()`;
